"const fs = require('fs');
const path = require('path');

// Search both local transcript_extract.jsonl and system generated logs
const logsDir = 'C:/Users/nikil/.gemini/antigravity/brain/0e775f5d-2f75-428a-b8bd-06b570f9a456/.system_generated/logs';
const transcriptPath = path.join(logsDir, 'transcript.jsonl');
const workspaceExtractPath = 'c:/Users/nikil/Downloads/fialgo-connect-main/fialgo-connect-main/transcript_extract.jsonl';

console.log('Searching in logs...');

function searchInFile(filePath) {
   if (!fs.existsSync(filePath)) {
      console.log('File does not exist:', filePath);
      return;
   }
   console.log('Reading:', filePath);
   const lines = fs.readFileSync(filePath, 'utf8').split('\n');
   let foundCount = 0;

   for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      if (!line) continue;
      try {
         const obj = JSON.parse(line);
         // Check if this contains view_file tool output for Settings.tsx
         const contentStr = JSON.stringify(obj);
         if (contentStr.includes('Settings.tsx') && (contentStr.includes('Total Lines: 2604') || contentStr.includes('Total Lines: 2855') || contentStr.includes('Total Lines:'))) {
            console.log(`Found candidate at line ${i}, type: ${obj.type}, status: ${obj.status}`);
            foundCount++;
            // Write this candidate line to a temp file for inspection
            fs.writeFileSync(`candidate_${foundCount}.json`, line, 'utf8');
         }
      } catch (e) {
         // ignore parse errors
      }
   }
   console.log(`Found ${foundCount} matches in ${filePath}`);
}

searchInFile(transcriptPath);
searchInFile(workspaceExtractPath);
"
